from pathlib import Path
import subprocess,json,shutil
r=Path.cwd()
def git(*a):return subprocess.check_output(['git',*a],text=True).strip()
audit=json.loads((r/'build/publication-audit101.json').read_text(encoding='utf8'));assert audit['passed'] and audit['remoteFetched']
release=git('rev-parse','readme-101^{commit}');assert release==audit['commit']==git('rev-parse','HEAD');tag=git('rev-parse','readme-101')
data={'edition':101,'releaseCommit':release,'annotatedTag':'readme-101','tagObject':tag,'audit':audit,'scope':'Actual non-force atomic main/edition101/tag push, fetched and independently audited from Git blobs. Actual local-model whole data-to-creation chat workflows, interruption/resume, source-derived contracts, four-state audits and fresh-input whole-skill reuse passed. Independent read-only review and retained failed attempts are documented. Retained initial failures are part of the original evidence. Post-push CI is separate.','analysis':json.loads((r/'build/analysis101.json').read_text(encoding='utf8')),'releaseCI':json.loads((r/'build/ci101-release.json').read_text(encoding='utf8'))}
(r/'docs/PUBLICATION_101.json').write_text(json.dumps(data,indent=2)+'\n',encoding='utf8')
folder=r/'docs/publication101';folder.mkdir(exist_ok=True)
for name in ['ci101-release.json', 'publication-audit101.json', 'push101.log', 'release101.py', 'audit-publication101.py', 'publication101.py', 'finish-publication101.py', 'freeze101.py', 'document101.py', 'guide101-template.html', 'check-guide101.cjs', 'visual101.json', 'visual-review101.json', 'documentation-check.json', 'doc-check101.log', 'guide101.log','guide101-initial.log', 'guide101-1440.png', 'guide101-390.png', 'ci101-status.json', 'analysis101.json', 'java101-initial.log', 'java101-final.log', 'java101-corrected.log', 'java101-resume.log', 'java101-resume-compile-failure.log', 'java101-resume-fixture-failure.log', 'desktop101-final.log', 'desktop101-new-final.log', 'renderer101.log', 'model101.log', 'model101-resumed.log','model101-final.log','model101-ui-race.log','model101-child-reconcile.log','model101-state-get.log','review101.cjs','review101.log','source-comparison101.json']:
 if (r/'build'/name).is_file():shutil.copyfile(r/'build'/name,folder/name)
notice=f"Published release {release}; annotated readme-101 tag object {tag}. Actual main/edition101/tag push fetched and verified: {audit['canonicalSourceFiles']} canonical sources, {audit['frozenHashes']} frozen hashes across101 editions and {audit['original101EvidenceFiles']} logical original archive entries. "
for name,link in [('AGENTS.md','docs/PUBLICATION_101.json'),('docs/PROJECT_MEMORY.md','PUBLICATION_101.json'),('docs/DEVELOPMENT_LOG.md','PUBLICATION_101.json'),('docs/ARCHITECTURE.md','PUBLICATION_101.json'),('README-CONTRIBUTORS.md','docs/PUBLICATION_101.json')]:
 p=r/name;s=p.read_text(encoding='utf8');assert '## Edition101 — locally verified; publication pending' in s;s=s.replace('## Edition101 — locally verified; publication pending','## Edition101 — published and fetched back\n\n'+notice+'[Publication receipt]('+link+').',1).replace('Main/tag publication and fetched receipt still pending.','Main/tag publication and fetched-content audit completed. Post-push CI is separate.',1);p.write_text(s,encoding='utf8',newline='\n')
p=r/'README.md';p.write_text(p.read_text(encoding='utf8').replace('Publication receipt follows the actual push and fetched-content audit.','Published to main. [Fetched GitHub verification](docs/PUBLICATION_101.json).'),encoding='utf8',newline='\n')
p=r/'docs/obsidian/109-durable-data-creation.md';p.write_text(p.read_text(encoding='utf8')+'\n'+notice+'[[docs/PUBLICATION_101.json|Publication receipt]]\n',encoding='utf8',newline='\n')
print(notice)
